import java.util.Arrays;import java.util.Scanner;
class Candidate implements Comparable<Candidate>{private final String name;private final double cgpa;private final int codingScore;public Candidate(String name,double cgpa,int codingScore){this.name=name;this.cgpa=cgpa;this.codingScore=codingScore;}public static boolean isEligible(double cgpa){return cgpa>=7.5;}public static boolean isEligible(double cgpa,int codingScore){return cgpa>=6.5&&codingScore>=60;}private double compositeScore(){return cgpa*10+codingScore;}public int compareTo(Candidate other){return Double.compare(other.compositeScore(),this.compositeScore());}public String getName(){return name;}public double getCgpa(){return cgpa;}public int getCodingScore(){return codingScore;}public double getCompositeScore(){return compositeScore();}}
public class PlacementDriveShortlistingRankingEngine {
 static String shortlistAndRank(Candidate[] candidates){Candidate[] shortlisted=new Candidate[candidates.length];int count=0;for(Candidate c:candidates)if(Candidate.isEligible(c.getCgpa())||Candidate.isEligible(c.getCgpa(),c.getCodingScore()))shortlisted[count++]=c;shortlisted=Arrays.copyOf(shortlisted,count);Arrays.sort(shortlisted);StringBuilder result=new StringBuilder();for(int i=0;i<shortlisted.length;i++){if(i>0)result.append(" | ");result.append(i+1).append(". ").append(shortlisted[i].getName()).append(" (").append(String.format("%.1f",shortlisted[i].getCompositeScore())).append(")");}return result.toString();}
 public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();Candidate[] candidates=new Candidate[n];for(int i=0;i<n;i++)candidates[i]=new Candidate(sc.next(),sc.nextDouble(),sc.nextInt());System.out.println(shortlistAndRank(candidates));sc.close();}
}